## Step 2: Create Services/CatalogService.cs

```csharp
using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new Department { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _courses = new List<Course>
        {
            new Course { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, loops, methods, and object-oriented basics.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", IsFeatured = true },
            new Course { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and has published over 30 papers in top CS conferences.", IsFeatured = true },
            new Course { Id = 3, DepartmentId = 1, Title = "Web Application Development", Code = "CS 340", Description = "Build modern web applications using ASP.NET Core, Blazor, and cloud services. Covers front-end and back-end development.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Carol Wang", InstructorBio = "Prof. Wang is a full-stack developer turned educator with industry experience at major tech companies.", IsFeatured = true },
            new Course { Id = 4, DepartmentId = 1, Title = "Database Systems", Code = "CS 360", Description = "Design and implementation of relational databases. Topics include SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim has extensive experience in database optimization and distributed systems.", IsFeatured = false },
            new Course { Id = 5, DepartmentId = 2, Title = "Calculus I", Code = "MATH 151", Description = "Introduction to differential calculus. Topics include limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an award-winning mathematics educator with a passion for making calculus accessible.", IsFeatured = true },
            new Course { Id = 6, DepartmentId = 2, Title = "Linear Algebra", Code = "MATH 220", Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Frank Nguyen", InstructorBio = "Dr. Nguyen researches applications of linear algebra in machine learning and data science.", IsFeatured = false },
            new Course { Id = 7, DepartmentId = 2, Title = "Discrete Mathematics", Code = "MATH 250", Description = "Logic, sets, combinatorics, graph theory, and proof techniques essential for computer science.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an award-winning mathematics educator with a passion for making calculus accessible.", IsFeatured = false },
            new Course { Id = 8, DepartmentId = 3, Title = "General Physics I", Code = "PHYS 201", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions for hands-on experimentation.", Credits = 4, Schedule = "Mon/Wed 8:00–9:20 AM, Lab: Fri 1:00–3:50 PM", InstructorName = "Dr. Grace Park", InstructorBio = "Dr. Park is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = true },
            new Course { Id = 9, DepartmentId = 3, Title = "Electromagnetism", Code = "PHYS 301", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM, Lab: Wed 2:00–4:50 PM", InstructorName = "Dr. Henry Okafor", InstructorBio = "Dr. Okafor specializes in electromagnetic theory and photonics research.", IsFeatured = false },
            new Course { Id = 10, DepartmentId = 3, Title = "Quantum Mechanics", Code = "PHYS 401", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, operators, and measurement.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Grace Park", InstructorBio = "Dr. Park is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}
