@page "/"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Home - University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h2 class="display-5">Welcome to State University</h2>
    <p class="lead text-muted">Explore our course catalog, find the right classes, and enroll today.</p>
    <a href="/courses" class="btn btn-primary btn-lg me-2">Browse Courses</a>
    <a href="/enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h3>Featured Courses</h3>
    <div class="row">
        @foreach (var course in CatalogService.GetFeaturedCourses())
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Title</h5>
                        <p class="card-text text-muted">@course.Code · @course.Credits credits</p>
                        <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h3>Departments</h3>
    <div class="list-group">
        @foreach (var dept in CatalogService.GetDepartments())
        {
            <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
                <strong>@dept.Name</strong> (@dept.Code) — @dept.Description
            </a>
        }
    </div>
</section>
