@page "/courses"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Browse Courses - University Course Catalog</PageTitle>

<h2>Browse Courses</h2>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title or code..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Any())
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <div class="alert alert-warning">Course not found.</div>
    <a href="/courses">← Back to Courses</a>
}
else
{
    <PageTitle>@course.Title - University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <h2>@course.Title</h2>
    <span class="badge bg-secondary mb-3">@course.Code</span>

    <div class="row mt-3">
        <div class="col-md-8">
            <h5>Description</h5>
            <p>@course.Description</p>

            <h5>Instructor</h5>
            <p><strong>@course.InstructorName</strong></p>
            <p>@course.InstructorBio</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <ul class="list-unstyled">
                        <li><strong>Credits:</strong> @course.Credits</li>
                        <li><strong>Schedule:</strong> @course.Schedule</li>
                        <li><strong>Department:</strong> @(department?.Name ?? "Unknown")</li>
                    </ul>
                    <a href="/enroll?courseId=@course.Id" class="btn btn-primary w-100">Enroll in this Course</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
            department = CatalogService.GetDepartment(course.DepartmentId);
    }
}

@page "/departments"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Departments - University Course Catalog</PageTitle>

<h2>Departments</h2>

<div class="row">
    @foreach (var dept in CatalogService.GetDepartments())
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text text-muted">@dept.Code</p>
                    <p class="card-text">@dept.Description</p>
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-primary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h2>Enrollment Request</h2>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for the selected course has been received.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <p class="text-muted">Fill out the form below to request enrollment in a course.</p>

    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm" class="row g-3" style="max-width: 600px;">
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="col-12">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" class="text-danger" />
        </div>

        <div class="col-12">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="col-12">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses(null, null))
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <div class="col-12">
            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </div>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

